<script setup lang="ts">
import {ref,reactive,watch} from 'vue'
import {ElMessage,ElMessageBox,type FormInstance} from 'element-plus'
import {api,post,type User} from '../api'
const props=defineProps<{section:string}>(),users=ref<User[]>([]),logs=ref<{id:number;actor:number;org:string;action:string;detail:unknown;created_at:string}[]>([]),dialog=ref(false),saving=ref(false),formRef=ref<FormInstance>()
const form=reactive({username:'',name:'',password:'',role:'farmer',org:'',district:'示范乡镇'})
async function load(){try{if(props.section==='users')users.value=await api('/admin/users');else logs.value=await api('/admin/audit')}catch(e){ElMessage.error((e as Error).message)}}
watch(()=>props.section,load,{immediate:true})
async function toggle(u:User){try{await ElMessageBox.confirm(`${u.active?'禁用':'启用'}账号 ${u.username}？`,'账号状态');await post(`/admin/users/${u.id}/toggle`,{});load()}catch(e){if(e instanceof Error)ElMessage.error(e.message)}}
async function save(){if(!await formRef.value?.validate().catch(()=>false))return;saving.value=true;try{await post('/admin/users',form);dialog.value=false;ElMessage.success('账号已创建');load()}catch(e){ElMessage.error((e as Error).message)}finally{saving.value=false}}
const resetUser=ref<User>(),resetPassword=ref(''),resetBusy=ref(false)
async function reset(){if(!resetUser.value||resetPassword.value.length<8){ElMessage.error('新密码至少 8 个字符');return}resetBusy.value=true;try{await post(`/admin/users/${resetUser.value.id}/password`,{new_password:resetPassword.value});resetUser.value=undefined;resetPassword.value='';ElMessage.success('密码已重置，原登录会话已失效')}catch(e){ElMessage.error((e as Error).message)}finally{resetBusy.value=false}}
function open(){Object.assign(form,{username:'',name:'',password:'',role:'farmer',org:'',district:'示范乡镇'});dialog.value=true}
</script>
<template><div class="page-title"><div><h1>{{section==='users'?'用户与数据权限':'操作审计'}}</h1><p>权限在后端校验，账号禁用后已有令牌无法继续访问</p></div><el-button v-if="section==='users'" type="primary" @click="open">新增账号</el-button></div><section class="panel"><el-table v-if="section==='users'" :data="users"><el-table-column prop="username" label="账号"/><el-table-column prop="name" label="名称"/><el-table-column prop="role" label="角色"/><el-table-column prop="org" label="经营主体"/><el-table-column prop="district" label="辖区"/><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.active?'success':'danger'">{{row.active?'启用':'禁用'}}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="{row}"><el-button link type="primary" @click="toggle(row)">{{row.active?'禁用':'启用'}}</el-button><el-button link @click="resetUser=row;resetPassword=''">重置密码</el-button></template></el-table-column></el-table><el-table v-else :data="logs"><el-table-column prop="created_at" label="时间" min-width="170"/><el-table-column prop="actor" label="用户 ID" width="90"/><el-table-column prop="org" label="主体"/><el-table-column prop="action" label="操作"/><el-table-column label="详情" min-width="240"><template #default="{row}"><span>{{JSON.stringify(row.detail)}}</span></template></el-table-column></el-table></section>
<el-dialog v-model="dialog" title="新增用户" width="550px" destroy-on-close><el-form ref="formRef" :model="form" label-position="top"><el-form-item label="账号" prop="username" :rules="[{required:true,message:'填写账号'},{pattern:/^[a-zA-Z0-9_-]{3,64}$/,message:'3–64 位字母、数字、下划线或短横线'}]"><el-input v-model="form.username" placeholder="例如 coop02"/></el-form-item><el-form-item label="姓名 / 主体名称" prop="name" :rules="[{required:true,message:'填写名称'}]"><el-input v-model="form.name"/></el-form-item><el-form-item label="初始密码" prop="password" :rules="[{required:true,message:'填写密码'},{min:8,message:'至少 8 个字符'}]"><el-input v-model="form.password" type="password" show-password autocomplete="new-password"/></el-form-item><el-form-item label="角色"><el-select v-model="form.role"><el-option label="合作社 / 种植大户" value="farmer"/><el-option label="乡镇农业监管员" value="regulator"/><el-option label="系统管理员" value="admin"/></el-select></el-form-item><el-form-item label="经营主体（相同主体共享生产数据）" prop="org" :rules="[{required:true,message:'填写所属主体'}]"><el-input v-model="form.org"/></el-form-item><el-form-item label="授权乡镇"><el-input v-model="form.district"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">创建账号</el-button></template></el-dialog><el-dialog :model-value="!!resetUser" title="重置用户密码" width="440px" @close="resetUser=undefined;resetPassword=''"><p>账号：{{resetUser?.username}}。重置后原登录会话失效。</p><el-input v-model="resetPassword" type="password" show-password :maxlength="128" autocomplete="new-password" placeholder="新密码至少 8 个字符"/><template #footer><el-button @click="resetUser=undefined">取消</el-button><el-button type="primary" :loading="resetBusy" @click="reset">确认重置</el-button></template></el-dialog></template>
